1	<!doctype html>
2	<!--
3	  Squelette de bannière événement LinkedIn (1600x900, 16:9), forme exécutable de Design-system §5.6.
4	  Même architecture que square.html : 1 CADRE générique + primitives. Aucun métier ici :
5	  le contenu est assemblé par le skill add-editorial-visual depuis le brief de la pièce.
6	  L'INSTANCE remplie vit dans 02-Areas/Éditorial/assets/event-banner-<sujet>.{html,png} (contenu par-pièce),
7	  jamais dans Brand/ (cf ADR-006 : Brand = specs/squelettes + identité réutilisable).
8	  Layout auto-layout CSS (flex), aucune coordonnée absolue sauf la barre accent (signature, ancrée au cadre).
9	  Rendu : node Brand/_pipeline/render-html.mjs <html> <out.png> 1600 900.
10	  Slots remplis par le skill : kicker | title | subtitle.
11	-->
12	<html lang="fr">
13	<head>
14	<meta charset="utf-8">
15	<link rel="preconnect" href="https://fonts.googleapis.com">
16	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
17	<link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;700&display=block" rel="stylesheet">
18	<style>
19	  /* ====== Tokens (Design-system §1.1 + dérivé rgba codifié §5.5/§5.6) ====== */
20	  :root {
21	    --bg:#FAF6EE; --surface:#FFFDF8; --indigo:#261961; --muted:#5C5278;
22	    --accent:#C68A14; --accent-soft:#F2E3B8; --border:#E8DEC8; --warning:#8A5A0A;
23	    --indigo-soft:rgba(38,25,97,0.08);
24	  }
25	  * { margin:0; padding:0; box-sizing:border-box; }
26	  body { font-family:'Manrope',system-ui,sans-serif; }
27	
28	  /* ====== CADRE générique bannière événement (§5.6) ====== */
29	  .banner {
30	    width:1600px; height:900px; position:relative;
31	    background-color:var(--bg);
32	    background-image:radial-gradient(circle, var(--indigo-soft) 1px, transparent 1px);
33	    background-size:20px 20px;
34	    padding:96px 140px;
35	    display:flex; flex-direction:column; align-items:center; justify-content:center; gap:30px;
36	  }
37	  .accent-bar { position:absolute; top:72px; left:140px; width:96px; height:5px; background:var(--accent); }
38	  /* Marque de série canonique "❯ live tech_" = ÉLÉMENT FIXE (§5.5 SSoT). Vocabulaire de classes aligné carrousel §5.8 (.series/.prompt/.stk/.cur). Ambre = glyphes décoratifs (prompt, curseur), jamais texte. */
39	  .topmatter { display:flex; flex-direction:column; align-items:center; gap:16px; }
40	  .series { font-size:46px; font-weight:800; letter-spacing:-1px; line-height:1; color:var(--indigo); display:flex; align-items:baseline; gap:12px; }
41	  .series .prompt { font-family:'JetBrains Mono',monospace; font-weight:700; font-size:.8em; color:var(--accent); }
42	  .series .stk { background:var(--accent-soft); border-radius:8px; padding:0 12px 4px; transform:rotate(-1.5deg); display:inline-block; }
43	  .series .cur { font-family:'JetBrains Mono',monospace; font-weight:700; color:var(--accent); }
44	  /* Kicker = date/heure de l'event (le NOM de série est porté par la marque fixe ci-dessus). */
45	  .kicker { font-family:'JetBrains Mono',monospace; font-size:30px; font-weight:700; letter-spacing:5px; text-transform:uppercase; color:var(--warning); }
46	  /* Titre : base 700 ; fragment .hl surligné en 800 (emphase = bold, §5.6). */
47	  .title { font-size:104px; font-weight:700; line-height:1.2; color:var(--indigo); text-align:center; }
48	  /* Surligneur peint depuis le bas (haut libre -> ne mord pas la jambe de la ligne au-dessus), technique partagée §5.8. */
49	  .title .hl { background-image:linear-gradient(var(--accent-soft),var(--accent-soft)); background-size:100% 82%; background-position:0 100%; background-repeat:no-repeat; border-radius:10px; padding:0 .1em; font-weight:800; box-decoration-break:clone; -webkit-box-decoration-break:clone; }
50	  .subtitle { font-size:36px; font-weight:500; color:var(--muted); text-align:center; }
51	  .identity { margin-top:22px; }
52	  .wordmark { width:269px; height:auto; } /* logo/sources/wordmark-color-light.svg inliné (viewBox 523, encre centrée) */
53	</style>
54	</head>
55	<body>
56	<div class="banner">
57	  <div class="accent-bar"></div>
58	
59	  <div class="topmatter">
60	    <!-- Marque de série FIXE (jamais un slot) : identité constante de tous les event-banners (§5.5 SSoT). -->
61	    <div class="series"><span class="prompt">❯</span>live <span class="stk">tech</span><span class="cur">_</span></div>
62	    <!-- slot:kicker:start --><div class="kicker">Jour JJ/MM · HHh</div><!-- slot:kicker:end -->
63	  </div>
64	  <!-- slot:title:start --><div class="title">Titre du live,<br><span class="hl">fragment clé</span></div><!-- slot:title:end -->
65	  <!-- slot:subtitle:start --><div class="subtitle">Sous-titre de cadrage, une phrase.</div><!-- slot:subtitle:end -->
66	
67	  <div class="identity">
68	    <!-- logo/sources/wordmark-color-light.svg, inliné tel quel (ancre d'identité, co-branding §04-Logo §5) -->
69	    <svg class="wordmark" viewBox="0 0 523 140" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="BGA Consulting">
70	      <text x="10" y="100" style="font-family:'Manrope',system-ui,sans-serif; font-weight:800; font-size:96px; fill:#261961; letter-spacing:-1px;">BGA</text>
71	      <circle cx="262" cy="88" r="6" fill="#C68A14"/>
72	      <text x="285" y="100" style="font-family:'Manrope',system-ui,sans-serif; font-weight:500; font-size:44px; fill:#5C5278; letter-spacing:0px;">Consulting</text>
73	    </svg>
74	  </div>
75	</div>
76	</body>
77	</html>
